class Solution {
public:
    int maximumLength(vector<int>& nums) {
        int n = nums.size();
        int ans = 0;
        for (int start = 0; start < 2; start++) {
            for (int same = 0; same < 2; same++) {
                int cnt = 0;
                int expect = start;
                for (int i = 0; i < n; i++) {
                    int p = nums[i] & 1;
                    if (p == expect) {
                        cnt++;
                        if (!same) expect = 1 - expect;
                    }
                }
                if (cnt > ans) ans = cnt;
            }
        }
        return ans;
    }
};
